"""Export untouched Daybreak float32 masters and four-role source-bank policy.

--check compares retained inputs/generated bytes offline; no decoder or network runs.
Native dispatch, shuffle, cap-zero semantics and listener/bus mix remain unverified.
"""
from pathlib import Path
import hashlib
import json
import math
import sys
import subprocess
def require(condition, message):
    if not condition:
        raise ValueError(message)

require(all(arg == '--check' for arg in sys.argv[1:]), 'Unknown argument')

sha = lambda b: hashlib.sha256(b).hexdigest()
graph_path = Path('docs/reference/leona-q-audio.json')
graph = json.loads(graph_path.read_text())
decoded = json.loads(Path('docs/reference/leona-q-audio-decoded.json').read_text())
require(decoded['sourceGraphSha256'] == sha(graph_path.read_bytes()), 'Source export constraint failed')
for item in graph['bankSources']:
    raw = Path(item['localPath']).read_bytes()
    require(len(raw) == item['bytes'] and sha(raw) == item['sha256'], 'Source export constraint failed')
xml = graph['parserXml']
require(sha(Path(xml['path']).read_bytes()) == xml['sha256'], 'Source export constraint failed')
for item in graph['media']:
    raw = (Path('.cache/leona-q-audio-media-v1-20261024') / f"{item['id']}.wem").read_bytes()
    require(len(raw) == item['bytes'] and sha(raw) == item['sha256'], 'Source export constraint failed')
nodes = {n['id']: n for n in graph['nodes']}

def parameter(identity, suffix, optional=False):
    found = [p for p in nodes[identity]['parameters'] if p[0].endswith('/' + suffix)]
    if optional and (not found):
        return None
    require(len(found) == 1, (identity, suffix))
    return found[0][2]

def properties(identity):
    fields = nodes[identity]['parameters']
    result = {}
    for f in fields:
        if f[0].endswith('/pID'):
            key = f[3].split('[')[-1].removesuffix(']')
            value = next((p[2] for p in fields if p[0] == f[0][:-3] + 'pValue'))
            require(key not in result, 'Source export constraint failed')
            result[key] = float(value)
    return result
events = {e['name']: e for e in graph['events']}
profile, outputs = ({}, {})
policy_fields = ['eMode', 'eRandomMode', 'wAvoidRepeatCount', 'bResetPlayListAtEachPlay', 'bIsGlobal', 'bIsContinuous', '_bIsUsingWeight', 'u16MaxNumInstance', 'bKillNewest', 'sLoopCount', 'sLoopModMin', 'sLoopModMax', 'eTransitionMode']
for role, suffix, target, gain, cap, newest in [('cast', 'LeonaShieldOfDaybreak_OnCast', 2429, -8, 2, 0), ('attack', 'LeonaShieldOfDaybreakAttack_OnCast', 2432, -11, 4, 0), ('hit', 'LeonaShieldOfDaybreakAttack_hit', 2431, -9, 2, 0), ('buff', 'LeonaShieldOfDaybreak_OnBuffActivate', 394358931, -17, 0, 0)]:
    event = events['Play_sfx_Leona_' + suffix]
    require(len(event['actions']) == 1, 'Source export constraint failed')
    action = event['actions'][0]
    require(action['target'] == target, 'Source export constraint failed')
    require(properties(action['id']) == ({'TransitionTime': 100} if role == 'buff' else {}), 'Source export constraint failed')
    require(int(parameter(action['id'], 'eFadeCurve')) == 4, 'Source export constraint failed')
    authored = properties(target)
    require(authored['MakeUpGain'] == gain, 'Source export constraint failed')
    pitch = authored.get('Pitch', 0)
    require(pitch == 0 and 'Pitch' not in authored, 'Source export constraint failed')
    require(int(parameter(target, 'DirectParentID')) == 2427, 'Source export constraint failed')
    policy = {k: int(v) for k in policy_fields if (v := parameter(target, k, True)) is not None}
    require(policy['u16MaxNumInstance'] == cap and policy['bKillNewest'] == newest, 'Source export constraint failed')
    direct = nodes[target]['type'] == 'CAkSound'
    if direct:
        require(role == 'buff', 'Source export constraint failed')
        sounds = [target]
    else:
        require(nodes[target]['type'] == 'CAkRanSeqCntr', 'Source export constraint failed')
        require({k: policy[k] for k in policy if k not in ['u16MaxNumInstance', 'bKillNewest']} == dict(eMode=0, eRandomMode=1, wAvoidRepeatCount=0, bResetPlayListAtEachPlay=1, bIsGlobal=1, bIsContinuous=0, _bIsUsingWeight=0, sLoopCount=1, sLoopModMin=0, sLoopModMax=0, eTransitionMode=0), 'Source export constraint failed')
        count = int(parameter(target, 'ulPlayListItem'))
        require(count == 4, 'Source export constraint failed')
        sounds = [int(parameter(target, f'AkPlaylistItem:{i}/ulPlayID')) for i in range(count)]
        require(all((int(parameter(target, f'AkPlaylistItem:{i}/weight')) == 50000 for i in range(count))), 'Source export constraint failed')
    variants = []
    for sound in sounds:
        sound_properties = properties(sound)
        require(sound_properties.get('Loop') == (0 if role == 'buff' else None), 'Source export constraint failed')
        identity = int(parameter(sound, 'sourceID'))
        m = next((m for m in decoded['media'] if m['id'] == identity))
        require(m['sampleRate'] == 44100 and m['channels'] == 1, 'Source export constraint failed')
        require(m['decoderMetadata']['loopingInfo'] is None, 'Source export constraint failed')
        raw = (Path('.cache/leona-q-audio-decoded-v1-20261024') / f'{identity}.wav').read_bytes()
        require(sha(raw) == m['wavSha256'], 'Source export constraint failed')
        url = f'assets/audio/leona-q-{identity}.wav'
        outputs['public/' + url] = raw
        variants.append(dict(id=identity, soundId=sound, url=url, sha256=m['wavSha256'], pcmSha256=m['pcmSha256'], frames=m['frames'], sampleRate=m['sampleRate'], channels=m['channels'], durationSeconds=m['durationSeconds'], peak=m['peak'], authoredProperties=sound_properties))
    require({v['id'] for v in variants} == set(action['affectedMediaIds']), 'Source export constraint failed')
    stop = None
    if role == 'buff':
        e = events['Stop_sfx_Leona_' + suffix]
        require(len(e['actions']) == 1, 'Source export constraint failed')
        a = e['actions'][0]
        props = properties(a['id'])
        require(a['target'] == target, 'Source export constraint failed')
        require(props == {'TransitionTime': 500}, 'Source export constraint failed')
        require(int(parameter(a['id'], 'eFadeCurve')) == 4, 'Source export constraint failed')
        stop = dict(eventId=e['id'], actionId=a['id'], targetId=target, delaySeconds=props.get('DelayTime', 0) / 1000, fadeSeconds=props.get('TransitionTime', 0) / 1000, curve=4, authoredProperties=props, missingPropertyPolicy='Absent delay/fade is locally bound to zero; native omitted-property defaults unverified.')
    profile[role] = dict(eventId=event['id'], actionId=action['id'], targetId=target, targetType=nodes[target]['type'], gainDb=gain, pitchCents=pitch, pitchProvenance='authored Pitch property' if 'Pitch' in authored else 'local zero for absent Pitch; native default unverified', fadeInSeconds=0.1 if role == 'buff' else 0, fadeInProvenance='authored 100ms play TransitionTime' if role == 'buff' else 'local zero for absent play TransitionTime; native default unverified', loop=role == 'buff', loopProvenance='authored Loop=0, interpreted infinite by pinned wwiser; native playback unobserved' if role == 'buff' else 'no authored Loop; finite random-container loop count 1', authoredProperties=authored, playProperties=properties(action['id']), policy=policy, capZeroPolicy='local unlimited; native cap-zero semantics unverified' if cap == 0 else None, stop=stop, variants=variants, maxDurationSeconds=max((v['durationSeconds'] for v in variants)))
require(properties(2427) == {} and int(parameter(2427, 'DirectParentID')) == 695650395, 'Source export constraint failed')
require(properties(695650395) == {'Priority': 60, 'AttenuationID': 339248780}, 'Source export constraint failed')
require(int(parameter(695650395, 'OverrideBusId')) == 1259461568, 'Source export constraint failed')
require(graph['unresolvedHierarchyIds'] == [1259461568], 'Source export constraint failed')
require(int(parameter(339248780, 'eScaling')) == 2, 'Source export constraint failed')
require(int(parameter(339248780, 'curveToUse[0]')) == 0, 'Source export constraint failed')
profile['attenuation'] = dict(id=339248780, scaling=2, points=[dict(distance=float(parameter(339248780, f'AkRTPCGraphPoint:{i}/From')), storedValue=float(parameter(339248780, f'AkRTPCGraphPoint:{i}/To')), interpolation=int(parameter(339248780, f'AkRTPCGraphPoint:{i}/Interp'))) for i in range(6)], unresolvedOutputBusId=1259461568)
profile['loopInterpretation'] = dict(file='.tools/wwiser/wwiser/generator/render/bnode_props.py', sha256='e9bfe9a8f3e2ea223ea8f7dba29c8921fbd7d220e62acaab61ba59bc5d751305', revision='71654ed1a2c4642894bd7e7ed79eba66986fb770', meaning='Loop=0 interpreted infinite by the pinned external reader, not observed native execution.')
require(sha(Path(profile['loopInterpretation']['file']).read_bytes()) == profile['loopInterpretation']['sha256'], 'Source export constraint failed')
profile['limits'] = ['Source Q media/authoring preparation only; playback and saved attack-attempt dispatch are not implemented by this exporter.', 'Native Q dispatch, shuffle/random sequence, cap-zero handling, effective voice inheritance and listener/bus mix remain unverified.', 'Decoded masters are untouched single-pass float32 PCM; no native loop-region, looping playback or listening comparison is established.', 'No authored Pitch; absent pitch/play-transition/stop-delay fields have explicitly labeled local zero bindings.']
source = '// Generated by tools/assets/export-leona-q-audio.py.\n// Untouched single-pass float32 masters; buff Loop=0 requires loop-aware playback; native dispatch/mix remain unverified.\n' + 'export const LEONA_Q_AUDIO = ' + json.dumps(profile, indent=2) + ' as const;\n'
outputs['src/content/leona-q-audio.ts'] = subprocess.check_output(['node_modules/.bin/prettier', '--stdin-filepath', 'src/content/leona-q-audio.ts'], input=source.encode())
timing = '// Generated by tools/assets/export-leona-q-audio.py.\n// Ceiling of untouched finite master durations at the local 60 Hz history clock.\n' + ''.join(f"export const LEONA_Q_{role.upper()}_AUDIO_TICKS = {math.ceil(profile[role]['maxDurationSeconds'] * 60)};\n" for role in ('cast', 'attack', 'hit'))
outputs['src/content/leona-q-audio-timing.ts'] = timing.encode()
for file, raw in outputs.items():
    path = Path(file)
    if '--check' in sys.argv:
        require(path.read_bytes() == raw, file)
    elif path.exists():
        require(path.read_bytes() == raw, 'Refuse to replace changed output: ' + file)
    else:
        path.write_bytes(raw)
print(json.dumps(dict(result='passed', checkOnly='--check' in sys.argv, events=len(events), roles=4, media=len(decoded['media']), shippedBytes=sum((len(b) for p, b in outputs.items() if p.endswith('.wav'))))))
